 76→            onClick={() => {
 77→              onClose();
 78→              setOpen(false);
 79→            }}
 80→            size="small"
 81→          >
 82→            Cancel
 83→          </Button>
 84→          <Button
 85→            as="button"
 86→            disabled={confirmDisabled}
 87→            onClick={(e) => {
 88→              onConfirm(e);
 89→              setOpen(false);
 90→            }}
 91→            size="small"
 92→            variant="primary"
 93→          >
 94→            {confirmText}
 95→          </Button>
 96→        </ButtonWrapper>
 97→      </ContentWrapper>
