import type { StorybookConfig } from '@storybook/react-vite';
import type { PluginOption } from 'vite';

/**
 * Vite plugin that polyfills Node's Buffer for the browser.
 * Required because @leafygreen-ui/emotion imports @emotion/server,
 * which transitively depends on buffer-from (a Node.js Buffer wrapper).
 */
function bufferPolyfillPlugin(): PluginOption {
  return {
    name: 'buffer-polyfill',
    transformIndexHtml() {
      return [
        {
          tag: 'script',
          attrs: { type: 'module' },
          children: `import { Buffer } from 'buffer'; globalThis.Buffer = globalThis.Buffer || Buffer;`,
          injectTo: 'head-prepend',
        },
      ];
    },
  };
}

const config: StorybookConfig = {
  stories: [
    '../src/**/*.mdx',
    '../src/**/*.stories.@(js|jsx|mjs|ts|tsx)',
    './eval-support/*.mdx',
  ],
  addons: [
    '@chromatic-com/storybook',
    '@storybook/addon-vitest',
    '@storybook/addon-a11y',
    '@storybook/addon-docs',
    '@storybook/addon-onboarding',
  ],
  framework: '@storybook/react-vite',
  staticDirs: ['../public'],
  viteFinal: async (config) => {
    config.plugins = config.plugins || [];
    config.plugins.push(bufferPolyfillPlugin());
    config.optimizeDeps = {
      ...config.optimizeDeps,
      include: [
        ...(config.optimizeDeps?.include || []),
        'buffer',
      ],
    };
    return config;
  },
};

export default config;

