  args: {
    currentPage: 4,
    totalResults: 50,
    pageSize: 10,
    onChange: fn(),
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('5 / 5')).toBeVisible();
  },
};

export const FirstPageDisabledPrev: Story = {
  args: {
    currentPage: 0,
    totalResults: 30,
    pageSize: 10,
    onChange: fn(),
  },
