 9→ * @returns The recent or default page size
10→ */
11→export const getDefaultPageSize = () => {
12→  const pageSizeFromLocalStorage = localStorage.getItem(RECENT_PAGE_SIZE_KEY);
13→  const pageSize = pageSizeFromLocalStorage
14→    ? parseInt(pageSizeFromLocalStorage, 10)
15→    : DEFAULT_PAGE_SIZE;
16→
17→  return PAGE_SIZES.includes(pageSize) ? pageSize : DEFAULT_PAGE_SIZE;
18→};
