import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn } from 'storybook/test';
import { TreeSelect, ALL_VALUE, TreeDataEntry } from './TreeSelect';

const sampleData: TreeDataEntry[] = [
  { title: 'All', value: ALL_VALUE, key: ALL_VALUE },
  {
    title: 'Fruits',
    value: 'fruits',
    key: 'fruits',
    children: [
      { title: 'Apple', value: 'apple', key: 'apple' },
      { title: 'Banana', value: 'banana', key: 'banana' },
      { title: 'Orange', value: 'orange', key: 'orange' },
    ],
  },
  {
    title: 'Vegetables',
    value: 'vegetables',
    key: 'vegetables',
    children: [
      { title: 'Carrot', value: 'carrot', key: 'carrot' },
      { title: 'Broccoli', value: 'broccoli', key: 'broccoli' },
    ],
  },
];

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return (
      <TreeSelect state={state} tData={sampleData} onChange={setState} />
    );
  },
  play: async ({ canvas }) => {
    const checkboxes = canvas.getAllByTestId('checkbox');
    // Should have All + Fruits + 3 fruit children + Vegetables + 2 veg children = 8
    await expect(checkboxes.length).toBe(8);
    await expect(canvas.getByText('All')).toBeVisible();
    await expect(canvas.getByText('Fruits')).toBeVisible();
    await expect(canvas.getByText('Apple')).toBeVisible();
  },
};

export const WithPreselected: Story = {
  render: () => {
    const [state, setState] = useState<string[]>(['apple', 'banana']);
    return (
      <TreeSelect state={state} tData={sampleData} onChange={setState} />
    );
  },
  play: async ({ canvas }) => {
    // Apple and Banana checkboxes should be checked
    const checkboxes = canvas.getAllByRole('checkbox');
    const appleCheckbox = canvas.getByLabelText('Apple');
    const bananaCheckbox = canvas.getByLabelText('Banana');
    await expect(appleCheckbox).toBeChecked();
    await expect(bananaCheckbox).toBeChecked();
  },
};

export const AllSelected: Story = {
  render: () => {
    const allValues = [
      ALL_VALUE,
      'fruits',
      'apple',
      'banana',
      'orange',
      'vegetables',
      'carrot',
      'broccoli',
    ];
    const [state, setState] = useState<string[]>(allValues);
    return (
      <TreeSelect state={state} tData={sampleData} onChange={setState} />
    );
  },
  play: async ({ canvas }) => {
    const allCheckbox = canvas.getByLabelText('All');
    await expect(allCheckbox).toBeChecked();
    const fruitsCheckbox = canvas.getByLabelText('Fruits');
    await expect(fruitsCheckbox).toBeChecked();
  },
};

export const ClickToSelect: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return (
      <TreeSelect state={state} tData={sampleData} onChange={setState} />
    );
  },
  play: async ({ canvas, userEvent }) => {
    const appleCheckbox = canvas.getByLabelText('Apple');
    await expect(appleCheckbox).not.toBeChecked();
    await userEvent.click(appleCheckbox);
    await expect(appleCheckbox).toBeChecked();
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import { http, HttpResponse } from 'msw';
import LoginPage from './index';

const meta = {
  component: LoginPage,
  tags: ['ai-generated'],
  parameters: {
    msw: {
      handlers: [
        // Override the default auth check to simulate unauthenticated state
        http.post('*/graphql/query', () =>
          HttpResponse.json({ errors: [{ message: 'Unauthorized' }] }, { status: 401 }),
        ),
        http.post('*/login', () => new HttpResponse(null, { status: 200 })),
      ],
    },
  },
} satisfies Meta<typeof LoginPage>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    ignoreAuthCheck: true,
  },
  play: async ({ canvas }) => {
    const usernameInput = canvas.getByLabelText('Username');
    const passwordInput = canvas.getByLabelText('Password');
    const loginButton = canvas.getByRole('button', { name: /login/i });

    await expect(usernameInput).toBeVisible();
    await expect(passwordInput).toBeVisible();
    await expect(loginButton).toBeVisible();
  },
};

export const FilledForm: Story = {
  args: {
    ignoreAuthCheck: true,
  },
  play: async ({ canvas, userEvent }) => {
    const usernameInput = canvas.getByLabelText('Username');
    const passwordInput = canvas.getByLabelText('Password');

    await userEvent.type(usernameInput, 'admin', { delay: 50 });
    await userEvent.type(passwordInput, 'password123', { delay: 50 });

    await expect(usernameInput).toHaveValue('admin');
    await expect(passwordInput).toHaveValue('password123');
  },
};

export const CssCheck: Story = {
  args: {
    ignoreAuthCheck: true,
  },
  play: async ({ canvas }) => {
    const loginButton = canvas.getByRole('button', { name: /login/i });
    // LoginPage uses a green background form. Verify the button is visible and styled.
    await expect(loginButton).toBeVisible();
    // The form wrapper uses display: flex and flex-direction: column
    const form = loginButton.closest('form');
    if (form) {
      const styles = getComputedStyle(form);
      await expect(styles.display).toBe('flex');
      await expect(styles.flexDirection).toBe('column');
    }
  },
};

