import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import ErrorBoundary from './index';

const ThrowingComponent = () => {
  throw new Error('Test error');
};

const meta = {
  component: ErrorBoundary,
  tags: ['ai-generated'],
} satisfies Meta<typeof ErrorBoundary>;

export default meta;
type Story = StoryObj<typeof meta>;

export const WithChild: Story = {
  args: {
    homeURL: '/',
    children: <div>App content renders normally</div>,
  },
  play: async ({ canvas }) => {
    await expect(
      canvas.getByText('App content renders normally'),
    ).toBeVisible();
  },
};

export const ErrorState: Story = {
  render: () => (
    <ErrorBoundary homeURL="/">
      <ThrowingComponent />
    </ErrorBoundary>
  ),
  play: async ({ canvas }) => {
    // The error fallback should show the error page
    await expect(canvas.getByTestId('error-fallback')).toBeVisible();
    await expect(canvas.getByText('Error')).toBeVisible();
    await expect(canvas.getByText(/sorry about that/i)).toBeVisible();
    await expect(
      canvas.getByRole('link', { name: /back to home/i }),
    ).toBeVisible();
  },
};

export const ErrorFallbackLink: Story = {
  render: () => (
    <ErrorBoundary homeURL="/dashboard">
      <ThrowingComponent />
    </ErrorBoundary>
  ),
  play: async ({ canvas }) => {
    const homeLink = canvas.getByRole('link', { name: /back to home/i });
    await expect(homeLink).toHaveAttribute('href', '/dashboard');
  },
};

