 3→
 4→/**
 5→ * Vite plugin that polyfills Node's Buffer for the browser.
 6→ * Required because @leafygreen-ui/emotion imports @emotion/server,
 7→ * which transitively depends on buffer-from (a Node.js Buffer wrapper).
 8→ */
 9→function bufferPolyfillPlugin(): PluginOption {
10→  return {
11→    name: 'buffer-polyfill',
12→    transformIndexHtml() {
13→      return [
14→        {
15→          tag: 'script',
16→          attrs: { type: 'module' },
17→          children: `import { Buffer } from 'buffer'; globalThis.Buffer = globalThis.Buffer || Buffer;`,
18→          injectTo: 'head-prepend',
19→        },
20→      ];
21→    },
22→  };
23→}
